sets=[('food','맛있는 숲','#fff1dc',[('apple','사과','This is an apple.'),('banana','바나나','I like bananas.'),('orange','오렌지','An orange is round.'),('grape','포도','This is a grape.'),('strawberry','딸기','The strawberry is red.'),('carrot','당근','A rabbit likes carrots.'),('bread','빵','I eat bread.'),('milk','우유','I drink milk.'),('egg','달걀','This is an egg.'),('cookie','쿠키','I like this cookie.'),('water','물','I drink water.'),('corn','옥수수','The corn is yellow.')]),('animals','동물 친구들','#eaf4eb',[('cat','고양이','The cat is cute.'),('dog','개','The dog can run.'),('rabbit','토끼','The rabbit can hop.'),('panda','판다','The panda eats bamboo.'),('lion','사자','The lion is big.'),('bear','곰','This is a bear.'),('fox','여우','The fox has a tail.'),('pig','돼지','The pig is pink.'),('bird','새','The bird can fly.'),('fish','물고기','The fish can swim.'),('turtle','거북이','The turtle is slow.'),('duck','오리','The duck can swim.')]),('school','두근두근 학교','#eeeafb',[('book','책','I read a book.'),('pencil','연필','This is my pencil.'),('bag','가방','This is my bag.'),('ruler','자','I have a ruler.'),('eraser','지우개','This is an eraser.'),('chair','의자','I sit on a chair.'),('desk','책상','My book is on the desk.'),('clock','시계','Look at the clock.'),('school','학교','I go to school.'),('paper','종이','I draw on paper.'),('crayon','크레용','This crayon is pink.'),('ball','공','I play with a ball.')]),('world','반짝이는 세상','#eaf3fd',[('sun','해','The sun is bright.'),('moon','달','I see the moon.'),('star','별','Look at the star.'),('tree','나무','The tree is green.'),('flower','꽃','This flower is pink.'),('cloud','구름','The cloud is white.'),('rain','비','I can hear the rain.'),('snow','눈','The snow is white.'),('house','집','This is my house.'),('car','자동차','The car is purple.'),('boat','배','The boat is on the water.'),('airplane','비행기','The airplane can fly.')])]
